BEGIN;
\echo === functions in public, ACL flags
SELECT p.oid::regprocedure AS fn, p.prosecdef AS def, has_function_privilege('anon',p.oid,'execute') anon, has_function_privilege('authenticated',p.oid,'execute') auth, has_function_privilege('service_role',p.oid,'execute') svc, (SELECT count(*)>0 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE a.grantee=0) as pub, (p.prorettype='trigger'::regtype) trg
FROM pg_proc p WHERE p.pronamespace='public'::regnamespace
AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')
ORDER BY 2 DESC, 3 DESC, 1::text;
\echo === default ACL
SELECT pg_get_userbyid(defaclrole) role, defaclnamespace::regnamespace ns, defaclobjtype, defaclacl FROM pg_default_acl WHERE defaclobjtype='f';
\echo === anon table privs
SELECT c.oid::regclass, c.relkind, has_table_privilege('anon',c.oid,'select') s, has_table_privilege('anon',c.oid,'insert') i, has_table_privilege('anon',c.oid,'update') u, has_table_privilege('anon',c.oid,'delete') d FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relkind IN ('r','v','m','p') ORDER BY 3 DESC, 1::text;
\echo === non-public functions owned by postgres
SELECT p.oid::regprocedure, p.pronamespace::regnamespace, has_function_privilege('anon',p.oid,'execute') anon FROM pg_proc p WHERE pg_get_userbyid(p.proowner)='postgres' AND p.pronamespace<>'public'::regnamespace AND p.pronamespace NOT IN ('pg_catalog'::regnamespace,'information_schema'::regnamespace) AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e');
\echo === policies
SELECT schemaname,tablename,policyname,cmd,roles,qual,with_check FROM pg_policies WHERE schemaname IN ('public','storage') ORDER BY 1,2,4;
ROLLBACK;
