docker exec -i supabase_db_test psql -U postgres -d postgres -X -P pager=off -q <<'SQL'
BEGIN;
SET LOCAL statement_timeout='20s';
SET LOCAL client_min_messages=notice;
DO $do$
DECLARE r record; n bigint; q text;
BEGIN
  PERFORM set_config('request.jwt.claims','{"role":"anon"}',true);
  SET LOCAL ROLE anon;
  FOR q IN SELECT unnest(ARRAY[
    'SELECT count(*) FROM (SELECT 1 FROM public."Space" LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.my_spaces LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.my_accounts LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.my_concepts LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.my_contents LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.my_documents LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.my_file_references LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.my_pseudo_accounts LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.my_groups LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.my_resource_grants LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.accounts_in_my_partial_spaces LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.my_contents_with_embedding_openai_text_embedding_3_small_1536 LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.concept_contributors LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.content_contributors LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.sync_info LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM public.group_membership LIMIT 1) x',
    'SELECT count(*) FROM (SELECT public.my_permissions_in_space(1)) x',
    'SELECT count(*) FROM (SELECT public.get_secret_token(''nope'')) x',
    'SELECT count(*) FROM (SELECT public.file_access(''nope'')) x',
    'SELECT count(*) FROM (SELECT public.rid_or_local_id_to_concept_db_id(''x'',1)) x',
    'SELECT count(*) FROM public.match_embeddings_for_subset_nodes(array_fill(0,ARRAY[1536])::extensions.vector, ARRAY[''a''])',
    'SELECT count(*) FROM (SELECT 1 FROM storage.objects LIMIT 1) x',
    'SELECT count(*) FROM (SELECT 1 FROM storage.buckets LIMIT 1) x'
  ]) LOOP
    BEGIN
      EXECUTE q INTO n;
      RAISE NOTICE 'OK    % -> %', q, n;
    EXCEPTION WHEN others THEN
      RAISE NOTICE 'ERR   % -> [%] %', q, SQLSTATE, SQLERRM;
    END;
  END LOOP;
END $do$;
ROLLBACK;
BEGIN;
SELECT e.extname, p.pronamespace::regnamespace ns, pg_get_userbyid(p.proowner) owner, count(*), bool_and(has_function_privilege('anon',p.oid,'execute')) anon_all, bool_and(has_function_privilege('authenticated',p.oid,'execute')) auth_all FROM pg_proc p JOIN pg_depend d ON d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e' JOIN pg_extension e ON e.oid=d.refobjid WHERE p.pronamespace NOT IN ('pg_catalog'::regnamespace) GROUP BY 1,2,3 ORDER BY 1;
SELECT rolname FROM pg_roles WHERE rolname !~ '^pg_' ORDER BY 1;
SELECT viewname, definition FROM pg_views WHERE viewname IN ('my_resource_grants');
SELECT c.relname, c.reloptions FROM pg_class c WHERE c.relname='my_resource_grants';
ROLLBACK;
SQL

